@use 'sass:map';
@use 'variables';
@use '../system';

@function get($colorName) {
  @if not map.has-key(variables.$colors, $colorName) {
    @error "Invalid color \"#{$colorName}\" specified! Choose one of #{map.keys(variables.$colors)}";
  }
  @return system.root-style(#{variables.$variable-prefix}color-#{$colorName});
}

@use 'sass:map';
@use 'sass:string';
@use 'variables';
@use 'functions';
@use '../system';

@mixin core-styles {
  @at-root {
    @each $colorName, $colors in variables.$colors {
      .#{variables.$class-prefix}color-#{'' + $colorName} {
        color: functions.get($colorName);
      }
      $onKey: 'on-' + $colorName;
      @if string.index($colorName, 'on-') != 1 {
        .#{variables.$class-prefix}bg-#{'' + $colorName} {
          background-color: functions.get($colorName);
          @if map.has-key(variables.$colors, $onKey) {
            color: functions.get($onKey);
          }
        }
      }
    }
  }
  .#{variables.$class-prefix}bg-transparent {
    background-color: transparent;
  }
}

@use '../system';

/// Prefix used for generated SRL CSS custom property names.
/// @type String
$variable-prefix: system.$variable-prefix !default;
/// Prefix used for generated SRL CSS class names.
/// @type String
$class-prefix: system.$class-prefix !default;

/// Named color definitions configured under colors.colors in srl.config.json.
/// @type Map
$colors: () !default;

@use 'system/variables' as systemVariables;
@use 'meta/variables' as metaVariables;
@use 'grid/variables' as gridVariables;
@use 'colors/variables' as colorsVariables;
@use 'typography/variables' as typographyVariables;
@use 'spacer/variables' as spacerVariables;
@use 'helpers/variables' as helpersVariables;

@use 'config';
@use 'index';
@use 'system/root';
@use "system/variables";

@use 'modern-css-reset';

h5,
h6,
ol,
ul,
li {
  margin: 0;
}

@if variables.$build != word {
  @include root.core-styles;
}
@include index.core-styles;
@include index.system-core-styles;
@include index.fonts-core-styles;
@include index.grid-core-styles;
@include index.colors-core-styles;
@include index.typography-core-styles;
@include index.spacer-core-styles;
@include index.helpers-core-styles;

@use "srl/fa" as v;

@font-face {
  font-family: 'Font Awesome 7 Brands';
  font-style: normal;
  font-weight: 400;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-brands-400.woff2');
}

@font-face {
  font-family: v.$family;
  font-style: normal;
  font-weight: 900;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-solid-900.woff2');
}

@use "srl/fa" as v;

@font-face {
  font-family: 'Font Awesome 7 Brands';
  font-style: normal;
  font-weight: 400;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-brands-400.woff2');
}

@font-face {
  font-family: v.$family;
  font-style: normal;
  font-weight: 100;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-thin-100.woff2');
}

@font-face {
  font-family: v.$family;
  font-style: normal;
  font-weight: 300;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-light-300.woff2');
}

@font-face {
  font-family: v.$family;
  font-style: normal;
  font-weight: 400;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-regular-400.woff2');
}

@font-face {
  font-family: v.$family;
  font-style: normal;
  font-weight: 900;
  font-display: v.$font-display;
  src: url('#{v.$font-path}/fa-solid-900.woff2');
}

@use "fa-source" as v;
@forward "fa-source";
@use "sass:map";
@use "sass:string";
@use "../system";

@mixin base {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  display: var(--#{v.$css-prefix}-display, #{v.$display});
  font-family: var(--_#{v.$css-prefix}-family);
  font-feature-settings: normal;
  font-style: normal;
  font-synthesis: none;
  font-variant: normal;
  font-weight: var(--#{v.$css-prefix}-style, #{v.$style});
  line-height: 1;
  text-align: center;
  text-rendering: auto;
  width: var(--#{v.$css-prefix}-width, #{v.$fw-width});
}

@mixin brands($icon) {
  @include content-before($icon, brands);
}

@mixin icon($icon) {
  @include content-before($icon, v.$default-style);
}

@mixin thin($icon) {
  @include content-before($icon, thin);
}

@mixin light($icon) {
  @include content-before($icon, light);
}

@mixin regular($icon) {
  @include content-before($icon, regular);
}

@mixin solid($icon) {
  @include content-before($icon, solid);
}

@mixin size($size) {
  @include v.fa-size($size);
}

@function find-font-weight($style) {
  @if v.$type == pro {
    @if $style == thin {
      @return 100;
    } @else if $style == light {
      @return 300;
    } @else if $style == regular {
      @return 400;
    } @else if $style == solid {
      @return 900;
    }
  }
  @return 900;
}

@mixin content($icon, $style: solid) {
  @if not map.has-key(v.$brand-icons, $icon) and not map.has-key(v.$icons, $icon) {
    @debug "Icon "#{$icon}" not found in Font Awesome 7.";
  } @else {
    $var: map.get(v.$brand-icons, $icon);
    @if $var != null {
      @include system.add-root-style(#{v.$css-prefix}-family-brands, '"Font Awesome 7 Brands"');
      @include system.add-root-style(#{v.$css-prefix}-font-brands, normal 400 1em/1 var(--#{v.$css-prefix}-family-brands));
      --#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family-brands);
      --#{v.$css-prefix}-style: 400;
      --_#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family, var(--#{v.$css-prefix}-style-family, "Font Awesome 7 Brands"));
      content: string.unquote("\"#{ $var }\"");
    } @else {
      $var: map.get(v.$icons, $icon);
      @include system.add-root-style(#{v.$css-prefix}-family-classic, '"#{ v.$family }"');
      @include system.add-root-style(#{v.$css-prefix}-font-#{$style}, normal #{find-font-weight($style)} 1em/1 var(--#{v.$css-prefix}-family-classic));
      @include system.add-root-style(#{v.$css-prefix}-style-family-classic, var(--#{v.$css-prefix}-family-classic));
      --#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family-classic);
      --#{v.$css-prefix}-style: #{find-font-weight($style)};
      --_#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family, var(--#{v.$css-prefix}-style-family, '#{v.$family}'));
      content: string.unquote("\"#{ $var }\"");
    }
  }
}

@mixin content-before($icon, $style: solid) {
  @if not map.has-key(v.$brand-icons, $icon) and not map.has-key(v.$icons, $icon) {
    @debug "Icon "#{$icon}" not found in Font Awesome 7.";
  } @else {
    $var: map.get(v.$brand-icons, $icon);
    @if $var != null {
      @include system.add-root-style(#{v.$css-prefix}-family-brands, '"Font Awesome 7 Brands"');
      @include system.add-root-style(#{v.$css-prefix}-font-brands, normal 400 1em/1 var(--#{v.$css-prefix}-family-brands));
      --#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family-brands);
      --#{v.$css-prefix}-style: 400;
      --_#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family, var(--#{v.$css-prefix}-style-family, "Font Awesome 7 Brands"));
      &::before {
        content: string.unquote("\"#{ $var }\"");
      }
    } @else {
      $var: map.get(v.$icons, $icon);
      @include system.add-root-style(#{v.$css-prefix}-family-classic, '"#{ v.$family }"');
      @include system.add-root-style(#{v.$css-prefix}-font-#{$style}, normal #{find-font-weight($style)} 1em/1 var(--#{v.$css-prefix}-family-classic));
      @include system.add-root-style(#{v.$css-prefix}-style-family-classic, var(--#{v.$css-prefix}-family-classic));
      --#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family-classic);
      --#{v.$css-prefix}-style: #{find-font-weight($style)};
      --_#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family, var(--#{v.$css-prefix}-style-family, '#{v.$family}'));
      &::before {
        content: string.unquote("\"#{ $var }\"");
      }
    }
  }
}

@use "sass:map";
@use "srl/meta";
@use "@fortawesome/fontawesome-free/scss/variables" with (
  $css-prefix: srl-icon,
  $icon-property: --srl-icon,
  $font-path: "@fortawesome/fontawesome-free/webfonts"
);
@forward "@fortawesome/fontawesome-free/scss/variables";
@forward "@fortawesome/fontawesome-free/scss/mixins";
/// Active Font Awesome package variant.
/// @type String
$type: free;
/// Default icon style selected by meta.icon.default-style.
/// @type String
$default-style: light;
@if map.has-key(meta.$meta, icon, default-style) {
  $default-style: map.get(meta.$meta, icon, default-style);
}

@use "sass:map";
@use "srl/meta";
@use "@fortawesome/fontawesome-pro/scss/variables" as v with (
  $css-prefix: srl-icon,
  $icon-property: --srl-icon,
  $font-path: "@fortawesome/fontawesome-pro/webfonts"
);
@use "@fortawesome/fontawesome-pro/scss/mixins" as m;
@forward "@fortawesome/fontawesome-pro/scss/variables";
@forward "@fortawesome/fontawesome-pro/scss/mixins";
/// Active Font Awesome package variant.
/// @type String
$type: pro;
/// Default icon style selected by meta.icon.default-style.
/// @type String
$default-style: light;
@if map.has-key(meta.$meta, icon, default-style) {
  $default-style: map.get(meta.$meta, icon, default-style);
}

@use 'variables';
@use 'sass:map';

@function is($font) {
  @return map.has-key(variables.$fonts, $font);
}

@function get($font) {
  @if not map.has-key(variables.$fonts, $font) {
    @error "Invalid font for fonts specified! Choose one of #{map.keys(variables.$fonts)}";
  }
  @return map.get(variables.$fonts, $font);
}

@function is-default() {
  @return variables.$default-font != '';
}

@function get-default() {
  @return variables.$default-font;
}

@use 'sass:map';
@use 'variables';
@use '../system';

@mixin core-styles {
  @each $font-family, $valFontFamily in variables.$fonts {
    @each $index, $font in map.get($valFontFamily, 'types') {
      $font-types: ();
      @each $format, $file in map.get($font, 'src') {
        $font-types: append(
          $font-types,
          'url("#{variables.$font-base-path}/#{$font-family}/#{$file}") format("#{$format}")',
          comma
        );
      }
      @font-face {
        font-family: '#{$font-family}';
        src: #{$font-types};
        @if map.has-key($font, 'font-weight') {
          font-weight: map.get($font, 'font-weight');
        }
        @if map.has-key($font, 'font-style') {
          font-style: '#{map.get($font, 'font-style')}';
        }
        @if map.has-key($font, 'font-display') {
          font-display: '#{map.get($font, 'font-display')}';
        }
      }
    }
  }
}

@use '../system';

/// Prefix used for generated SRL CSS class names.
/// @type String
$class-prefix: system.$class-prefix !default;
/// Prefix used for generated SRL CSS custom property names.
/// @type String
$variable-prefix: system.$variable-prefix !default;

/// Base URL or relative path used when generating font-face source URLs.
/// @type String
$font-base-path: '' !default;
/// Name of the font used when no explicit typography font is selected.
/// @type String
$default-font: '' !default;
/// Font-family and font-face definitions configured under fonts.fonts.
/// @type Map
$fonts: () !default;

@use 'sass:map';
@use 'variables';
@use '../system';


@function get-container-max-width() {
  @return system.root-style(#{variables.$variable-prefix}container-max-width, 0);
}

@function get-container-padding() {
  @return system.root-style(#{variables.$variable-prefix}container-padding, 0);
}

@function get-breakpoint($breakpoint) {
  @if not map.has-key(variables.$breakpoints, $breakpoint) {
    @error "Invalid breakpoint for container specified! Choose one of #{map.keys(variables.$breakpoints)}";
  }
  @return system.root-style(#{variables.$variable-prefix}-breakpoint-#{$breakpoint});
}

@function get-gutter-columns() {
  @return system.root-style(#{variables.$variable-prefix}gutter-columns);
}

@function get-gutter-row-gap() {
  @return system.root-style(#{variables.$variable-prefix}gutter-row-gap);
}

@function get-gutter-column-gap() {
  @return system.root-style(#{variables.$variable-prefix}gutter-column-gap);
}

@function calculate-pdf-col-span-minus-one-gutter($span) {
  $gaps-inside: $span - 1;
  $columns: map.get(variables.$columns, print);
  $gutter: get-gutter-column-gap();

  @return calc(
          ((100% - (#{$columns - 1} * #{$gutter})) * #{$span} / #{$columns}) + (#{$gaps-inside} * #{$gutter})
  );
}

@function calculate-pdf-col-span-plus-one-gutter($span) {
  $gaps-inside: $span + 1;
  $columns: map.get(variables.$columns, print);
  $gutter: get-gutter-column-gap();

  @return calc(
          ((100% - (#{$columns - 1} * #{$gutter})) * #{$span} / #{$columns}) + (#{$gaps-inside} * #{$gutter})
  );
}

@function calculate-pdf-col-start($start-col) {
  $columns: map.get(variables.$columns, print);
  $gutter: get-gutter-column-gap();
  $span: $start-col - 1;

  @return calc(
    ((100% - (#{$columns - 1} * #{$gutter})) * #{$span} / #{$columns}) + (#{$span} * #{$gutter})
  );
}

@use 'variables';
@use 'functions';
@use '../system';
@use 'sass:math';
@use 'sass:map';
@use 'sass:list';

@mixin media($breakpoint) {
  @if not map.has-key(variables.$breakpoints, $breakpoint) {
    @error "Invalid breakpoint \"#{$breakpoint}\" specified! Choose one of #{map.keys(variables.$breakpoints)}";
  }
  @if $breakpoint == print {
    @media print {
      @content;
    }
  } @else {
    $min: map.get(variables.$breakpoints, $breakpoint);
    @if $min == 0 {
      $min: false;
    }
    $next: system.map-get-next(variables.$breakpoints, $breakpoint);
    $max: false;
    @if $next {
      $max: $next - 1;
    }
    @if (not $min and $max) {
      @media screen and (max-width: #{system.size-unit($max)}) {
        @content;
      }
    } @else if ($min and not $max) {
      @media screen and (min-width: #{system.size-unit($min)}) {
        @content;
      }
    } @else if ($min and $max) {
      @media screen and (min-width: #{system.size-unit($min)}) and (max-width: #{system.size-unit($max)}) {
        @content;
      }
    } @else {
      @content;
    }
  }
}

@mixin media-up($breakpoint) {
  @if not map.has-key(variables.$breakpoints, $breakpoint) {
    @error "Invalid breakpoint \"#{$breakpoint}\" specified! Choose one of #{map.keys(variables.$breakpoints)}";
  }
  $min: map.get(variables.$breakpoints, $breakpoint);

  @if $min == 0 {
    @content;
  } @else {
    @media screen and (min-width: #{system.size-unit($min)}) {
      @content;
    }
  }
}

@mixin media-down($breakpoint) {
  @if not map.has-key(variables.$breakpoints, $breakpoint) {
    @error "Invalid breakpoint \"#{$breakpoint}\" specified! Choose one of #{map.keys(variables.$breakpoints)}";
  }
  $next: system.map-get-next(variables.$breakpoints, $breakpoint);
  $max: false;
  @if $next {
    $max: $next - 1;
  }
  @if $max {
    @media screen and (max-width: #{system.size-unit($max)}) {
      @content;
    }
  } @else {
    @error "Invalid max breakpoint #{$breakpoint} specified! Choose one of #{map.keys(map-remove(variables.$breakpoints, $breakpoint))}";
  }
}

@mixin media-between($breakpoint-min, $breakpoint-max) {
  @if (
    not
      map.has-key(variables.$breakpoints, $breakpoint-min) or not
      map.has-key(variables.$breakpoints, $breakpoint-max)
  ) {
    @error "Invalid breakpoint \"#{$breakpoint-min}\" or \"#{$breakpoint-max}\" specified! Choose one of #{map.keys(variables.$breakpoints)}";
  }
  $min: map.get(variables.$breakpoints, $breakpoint-min);
  @if $min == 0 {
    $min: false;
  }
  $next: system.map-get-next(variables.$breakpoints, $breakpoint-max);
  $max: false;
  @if $next {
    $max: $next - 1;
  }
  @if (not $min and $max) {
    @media screen and (max-width: #{system.size-unit($max)}) {
      @content;
    }
  } @else if ($min and not $max) {
    @media screen and (min-width: #{system.size-unit($min)}) {
      @content;
    }
  } @else if ($min and $max) {
    @media screen and (min-width: #{system.size-unit($min)}) and (max-width: #{system.size-unit($max)}) {
      @content;
    }
  } @else {
    @content;
  }
}

@mixin container-fluid {
  padding-inline: var(--#{variables.$variable-prefix}container-padding, unset);
}

@mixin container {
  max-width: var(--#{variables.$variable-prefix}container-max-width, unset);
  padding-inline: var(--#{variables.$variable-prefix}container-padding, unset);
}

@mixin row() {
  display: grid;
  grid-template-columns: repeat(
    var(--#{variables.$variable-prefix}gutter-columns),
    1fr
  );
  column-gap: var(--#{variables.$variable-prefix}gutter-column-gap);
  row-gap: var(--#{variables.$variable-prefix}gutter-row-gap);
}

@mixin col($span: false, $breakpoint-start: false, $breakpoint-end: false) {
  @if $breakpoint-start and $breakpoint-end and $span {
    @include media-between($breakpoint-start, $breakpoint-end) {
      width: auto;
      grid-column-end: span #{$span};
    }
  } @else if $breakpoint-start and $span {
    @include media($breakpoint-start) {
      width: auto;
      grid-column-end: span #{$span};
    }
  } @else if $span {
    width: auto;
    grid-column-end: span #{$span};
  } @else {
    width: auto;
    grid-column-end: span #{variables.$column-default-span};
  }
}

@mixin offset($offset, $breakpoint: false) {
  @if $breakpoint {
    @if not map.has-key(variables.$breakpoints, $breakpoint) {
      @error "Invalid breakpoint specified! Choose one of #{map.keys(variables.$breakpoints)}";
    }
    @include media($breakpoint) {
      grid-column-start: ($offset + 1);
    }
  } @else {
    grid-column-start: ($offset + 1);
  }
}

@mixin pdf-flex-col($span) {
  width: functions.calculate-pdf-col-span-minus-one-gutter($span);
}

@mixin core-styles {
}

@use "variables";
@use "../system";
@use "sass:map";

/// Smallest configured breakpoint used while generating grid root styles.
/// @type String | Null
/// @access private
$smallest-breakpoint: null;

@each $breakpoint, $min-width in variables.$breakpoints {
  @if $min-width == 0 {
    $smallest-breakpoint: $breakpoint;
  }
}

@each $breakpoint, $min-width in variables.$breakpoints {
  $breakpoint-map: $breakpoint;

  @if $breakpoint == $smallest-breakpoint {
    $breakpoint-map: false;
  }

  $size-unit: false;
  @if $breakpoint == print {
    $size-unit: in;
  }

  @include system.add-root-style(
                  #{variables.$variable-prefix}breakpoint-#{$breakpoint},
                  system.size-unit($min-width, $size-unit)
  );

  $container: map.get(variables.$containers, $breakpoint);

  $container-max-width: map.get($container, max-width);
  @if not $container-max-width {
    $container-max-width: unset;
  }

  @include system.add-root-style(
                  #{variables.$variable-prefix}container-max-width,
                  system.size-unit($container-max-width, $size-unit),
                  $breakpoint-map
  );

  $container-padding: map.get($container, padding);
  @if not $container-padding {
    $container-padding: unset;
  }

  @include system.add-root-style(
                  #{variables.$variable-prefix}container-padding,
                  system.size-unit($container-padding, $size-unit),
                  $breakpoint-map
  );

  $gutter: map.get(variables.$gutter, $breakpoint);
  @if not $gutter {
    $gutter: (
            columns: 1,
    );
  }

  $columns: map.get(variables.$columns, $breakpoint);

  $gap: map.get($gutter, gap);
  $row-gap: unset;
  $column-gap: unset;
  @if $gap {
    $row-gap: $gap;
    $column-gap: $gap;
  } @else {
    @if map.has-key($gutter, row-gap) {
      $row-gap: map.get($gutter, row-gap);
    }
    @if map.has-key($gutter, column-gap) {
      $column-gap: map.get($gutter, column-gap);
    }
  }

  @include system.add-root-style(
                  #{variables.$variable-prefix}gutter-columns,
                  $columns,
                  $breakpoint-map
  );
  @include system.add-root-style(
                  #{variables.$variable-prefix}gutter-row-gap,
                  system.size-unit($row-gap, $size-unit),
                  $breakpoint-map
  );

  @include system.add-root-style(
                  #{variables.$variable-prefix}gutter-column-gap,
                  system.size-unit($column-gap, $size-unit),
                  $breakpoint-map
  );
}

@use '../system';

/// Prefix used for generated SRL CSS class names.
/// @type String
$class-prefix: system.$class-prefix !default;
/// Prefix used for generated SRL CSS custom property names.
/// @type String
$variable-prefix: system.$variable-prefix !default;

/// Container widths and paddings keyed by breakpoint.
/// @type Map
$containers: () !default;
/// Ordered map of SRL breakpoint names to their minimum widths.
/// @type Map
$breakpoints: () !default;
/// Number of grid columns for each output or breakpoint.
/// @type Map
$columns: () !default;
/// Grid column and row gaps keyed by breakpoint.
/// @type Map
$gutter: () !default;

/// Column span used by grid-col when no explicit span is passed.
/// @type Number
$column-default-span: 4 !default;

@use '../system';
@use '../typography';
@use 'variables';

@mixin trim-margins {
  > * {
    &:first-child {
      margin-block-start: 0;
    }
    &:last-child {
      margin-block-end: 0;
    }
  }
}

@mixin list-reset() {
  list-style: none;
  margin: 0;
  padding: 0;
  li {
    margin: 0;
    padding: 0;
  }
}

@mixin list-default($list-style: circle) {
  list-style: #{$list-style};
  margin: system.size-unit(variables.$default-list-margin);
  padding: system.size-unit(variables.$default-list-padding);
  li {
    margin: system.size-unit(variables.$default-list-margin);
