@function _component-margin-selector($name) {
  @if $name == all {
    @return '*';
  }

  @if meta.type-of($name) == 'string' {
    $first: string.slice($name, 1, 1);

    @if $first ==
      '.' or
      $first ==
      '#' or
      $first ==
      '*' or
      $first ==
      '[' or
      $first ==
      ':'
    {
      @return $name;
    }
  }

  @return '.#{variables.$class-prefix}#{$name}';
}

@function _component-margin-rules($group-name) {
  @if not map.has-key(variables.$margins, group) {
    @error "No margin groups configured! Define spacer.margins.group in srl.config.json.";
  }

  $groups: map.get(variables.$margins, group);

  @if not map.has-key($groups, $group-name) {
    @error "Invalid margin group \"#{$group-name}\" specified! Choose one of #{map.keys($groups)}";
  }

  $group: map.get($groups, $group-name);
  $from: '.#{variables.$class-prefix}margin-group-#{$group-name}';
  $rules: ();

  @each $to, $margin in $group {
    $rules: map.merge(
            $rules,
            (
                            ($from, _component-margin-selector($to)): $margin,
            )
    );
  }

  @return $rules;
}

@function _component-margin-edge-selector($selector, $edge) {
  @if meta.type-of($selector) !=
    'string' or
    string.slice($selector, 1, 1) !=
    '.'
  {
    @return null;
  }

  @each $token in (' ', ':', '[', '#', '>', '+', '~', '*', ',') {
    @if string.index($selector, $token) {
      @return null;
    }
  }

  @return '#{$selector}-#{$edge}';
}

/// Generates vertical spacing between adjacent Livingdocs components.
/// Pass a margin-group name from `spacer.margins.group` or a custom map of
/// `(from-selector, to-selector): spacer-token` rules. A named group expects
/// the source component to carry `srl-margin-group-<name>` in its HTML. The
/// generated selectors also account for SRL wrappers and PDF edge variants.
/// @param {String | Map} $spacing-rules - Configured group name or custom selector-pair map.
/// @example scss
///   @include srl.spacer-component-margin(text);
///
///   $custom-margins: (
///     ('.srl-paragraph', '.srl-list-group'): 200,
///   );
///   @include srl.spacer-component-margin($custom-margins);
@mixin component-margin($spacing-rules) {
  @if meta.type-of($spacing-rules) != 'map' {
    $spacing-rules: _component-margin-rules($spacing-rules);
  }

  @each $pair, $margin in $spacing-rules {
    $from: list.nth($pair, 1);
    $to: list.nth($pair, 2);

    @if $to == '*' {
      #{$from} + * {
        @include margin-top($margin);
      }
    } @else {
      #{$from} + #{$to} {
        @include margin-top($margin);
      }
    }

    @if system.$build == 'pdf' {
      $from-first: _component-margin-edge-selector($from, 'first');
      $from-last: _component-margin-edge-selector($from, 'last');
      $to-first: _component-margin-edge-selector($to, 'first');

      @if $to == '*' {
        #{$from} + * {
          @include margin-top($margin);
        }

        @if $from-last {
          #{$from-last} + * {
            @include margin-top($margin);
          }
        }
      } @else {
        #{$from} + #{$to} {
          @include margin-top($margin);
        }

        @if $from-first {
          #{$from-first} + #{$to} {
            @include margin-top($margin);
          }
        }

        @if $from-first and $to-first {
          #{$from-first} + #{$to-first} {
            @include margin-top($margin);
          }
        }

        @if $to-first {
          #{$from} + #{$to-first} {
            @include margin-top($margin);
          }
        }

        @if $from-last {
          #{$from-last} + #{$to} {
            @include margin-top($margin);
          }
        }

        @if $from-last and $to-first {
          #{$from-last} + #{$to-first} {
            @include margin-top($margin);
          }
        }
      }
    } @else {
      $wrappers: null;

      @if system.$build != 'xbrl' {
        $wrappers: ('.srl-nested-container:not(.srl-aside-content-container)');
      } @else {
        $wrappers: (
                '.srl-nested-container:not(.srl-aside-content-container)',
                '.ixbrl-element'
        );
      }
      @each $wrapper in $wrappers {
        @if $to == '*' {
          #{$from} + #{$wrapper}:has(:first-child),
          #{$wrapper}:has(#{$from}:last-child) + * {
            @include margin-top($margin);
          }
        } @else {
          #{$from} + #{$wrapper}:has(#{$to}:first-child),
          #{$wrapper}:has(#{$from}:last-child) + #{$to},
          #{$wrapper}:has(#{$from}:first-child)
          + #{$wrapper}:has(#{$to}:last-child),
          #{$wrapper}:has(#{$from}:last-child)
          + #{$wrapper}:has(#{$to}:first-child) {
            @include margin-top($margin);
          }
        }
      }

      $aside-wrapper: '.srl-aside-content-container';
      $aside-content: '.srl-aside-content-container__content';

      @if $to == '*' {
        #{$from} + #{$aside-wrapper}:has(#{$aside-content} > :first-child),
        #{$aside-wrapper}:has(#{$aside-content} > #{$from}:last-child) + * {
          @include margin-top($margin);
        }
      } @else {
        #{$from}
        + #{$aside-wrapper}:has(#{$aside-content} > #{$to}:first-child),
        #{$aside-wrapper}:has(#{$aside-content} > #{$from}:last-child) + #{$to},
        #{$aside-wrapper}:has(#{$aside-content} > #{$from}:first-child)
        + #{$aside-wrapper}:has(#{$aside-content} > #{$to}:last-child),
        #{$aside-wrapper}:has(#{$aside-content} > #{$from}:last-child)
        + #{$aside-wrapper}:has(#{$aside-content} > #{$to}:first-child) {
          @include margin-top($margin);
        }

        @each $wrapper in $wrappers {
          #{$aside-wrapper}:has(#{$aside-content} > #{$from}:first-child)
          + #{$wrapper}:has(#{$to}:last-child),
          #{$wrapper}:has(#{$from}:last-child)
          + #{$aside-wrapper}:has(#{$aside-content} > #{$to}:first-child) {
            @include margin-top($margin);
          }
        }
      }
    }
  }
}

