@include index.helpers-core-styles;

@use 'srl';
@use 'web';

html {
  -webkit-text-size-adjust: 100%;
  scrollbar-gutter: stable;
}

html,
body {
  overscroll-behavior: none;
}

* {
  scroll-margin-top: calc(srl.system-root-style(srl-header-height) + srl.spacer-get(400));
}

.fade-enter-from {
  opacity: 0;
}

.fade-enter-to {
  opacity: 1;
}

.fade-enter-active {
  transition: opacity 300ms linear;
}

.fade-leave-from {
  opacity: 1;
}

.fade-leave-to {
  opacity: 0;
}

.fade-leave-active {
  transition: opacity 300ms linear;
}

@use "srl";
@use "srl/fa";
@use "srl/button";

$transition-duration: .3s;

.srl-category-accordion
{
  @include srl.spacer-margin-top(800);

  &__inner {

    @include srl.grid-media-up(tablet-pt) {
      display: grid;
      column-gap: var(--srl-container-padding);
      grid-template-columns:
        [start] minmax(0, 1fr)
        [content] minmax(0, calc(var(--srl-container-max-width) - var(--srl-container-padding) * 2))
        [end] minmax(0, 1fr)
        [full-end];
    }

    &-head {
      width: 100%;
      grid-column: content / end;
      @extend %srl-grid-base;
      @include srl.grid-media-up(tablet-pt) {
        padding-inline: 0;
      }
    }

    &:after {
      content: "";
      display: block;
      border-bottom: 1px solid srl.colors-primary-1000();
      grid-column: content / end;
      margin-inline: var(--srl-container-padding);
      @include srl.grid-media(tablet-pt) {
        margin-inline: 0;
      }
      @include srl.grid-media(tablet-ls) {
        margin-inline: calc(100% / var(--srl-gutter-columns) * 2 + 7px);
      }
      @include srl.grid-media-up(desktop) {
        margin-inline: calc(100% / var(--srl-gutter-columns) * 3 + 7px);
      }
    }
  }

  & + & {
    margin-block-start: 0;
  }

  &:has(+ .srl-category-accordion) {
    .srl-category-accordion__inner:after {
      display: none;
    }
  }

  &__head {
    border-style: solid;
    border-color: srl.colors-primary-1000();
    border-width: srl.system-size-unit(1) 0 0 0;

    @extend %srl-regular-width;

    &--btn {
      width: 100%;
      text-align: left;
      background-color: transparent;
      padding: srl.spacer-get(400) 0;
      @include srl.spacer-gap(200);
      cursor: pointer;
      display: flex;
      border: 0;
      align-items: flex-start;

      @include button.switch(".srl-category-accordion__icon");

      &[aria-expanded="true"] {
        .srl-category-accordion__icon {
          @include fa.icon(minus);
        }
      }
    }

    .srl-grid {
      display: flex;
      padding-inline: 0;
      margin-inline: 0;
    }

    &.srl-title-h2 {
      [class*="-number"],
      [class*="-text"]
      {
        @include srl.typography-title-h3();
      }
    }
    &.srl-title-h3 {
      [class*="-number"],
      [class*="-text"] {
        @include srl.typography-title-h4();
      }
    }
    &.srl-title-h4 {
      [class*="-number"],
      [class*="-text"] {
        @include srl.typography-title-h5();
      }
    }

    [class*="-number"],
    [class*="-text"]
    {
      @include srl.typography-title-h3();
      @include srl.spacer-margin-top(100);
    }

    [class$="-text"] {
      flex: 1 1 auto;
    }

    [class$="-number"] {
      flex: 0 0 auto;
      width: srl.spacer-get(800);
      color: srl.colors-black-1000();
    }

    .srl-category-accordion__icon {
      flex: 0 0 auto;
      @extend %srl-button;
      @extend %srl-button--icon;
      @extend %srl-icon-base;
      @include fa.icon(plus);

      &:before {
        @extend %srl-icon-base;
      }
    }

    &[aria-expanded="true"] {
      .srl-category-accordion__icon {
        background-color: srl.colors-black-1000();
        color: srl.colors-white-1000();
        border-color: srl.colors-black-1000();
      }
    }
  }

  &__content {
    display: grid;
    grid-template-rows: 1fr;
    transition: padding-bottom $transition-duration ease, grid-template-rows $transition-duration ease;
    grid-column: start / full-end;

    &[hidden] {
      grid-template-rows: 0fr;
      padding-bottom: 0;
    }

    &:not([hidden]) {
      padding-bottom: srl.spacer-get(400);
    }

    &-inner {
      width: 100%;
      padding: 0;
      overflow: hidden;

      .srl-category-accordion:last-child {
        > .srl-category-accordion__inner:after {
          display: none;
        }
      }
    }
  }
}

@use "srl";

body:has(.srl-page__dialog[open]) {
    overflow: hidden;
}
.srl-page__dialog[open] {
    border: none;
    padding: 0;
    width: srl.system-root-style(srl-container-max-width, 100%);
    max-width: 100%;
    max-height: 100dvh;
    background-color: transparent;

    &::backdrop {
        background: srl.colors-grey-400();
        opacity: 0.6;
    }
}


.srl-dialog {
    position: relative;
    background-color: srl.colors-white-1000();
    padding-block: srl.system-root-style(srl-container-padding, 0);
    max-height: 100dvh;
    display: flex;
    flex-direction: column;
    gap: srl.system-root-style(srl-container-padding, 0);
}

.srl-dialog__header,
.srl-dialog__footer {
    padding-inline: srl.system-root-style(srl-container-padding, 0);
}

.srl-dialog__header {
    flex: 0 0 auto;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: flex-end;
    align-items: flex-start;
    position: relative;
    gap: srl.grid-get-gutter-column-gap();
}

.srl-dialog__main {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: auto;

    padding-block-end: srl.system-root-style(srl-container-padding, 0);
    padding-inline-start: srl.system-root-style(srl-container-padding, 0);
    padding-inline-end: calc(srl.system-root-style(srl-container-padding, 0) / 4 * 3);
    margin-inline-end: calc(srl.system-root-style(srl-container-padding, 0) / 4);

    @media (hover: hover) {
        padding-inline-end: calc(srl.system-root-style(srl-container-padding, 0) / 4 * 3 - #{srl.system-size-unit(16)});
        scrollbar-gutter: stable;
    }

    .srl-grid,
    .srl-table__container > div,
    .srl-category-accordion__inner-head {
        padding-inline: 0;
        margin-inline: 0;
    }
}

.srl-dialog__header--body {
    flex: 1 1 auto;
}

.srl-dialog__footer {
    flex: 0 0 auto;
}

@include srl.grid-media-up(tablet-pt) {
    .srl-page__dialog[open] {
        border-radius: srl.system-size-unit(16);
    }
}

@use "sass:list";
@use "srl";
@use "srl/fa";

$brands: (
  facebook-f,
  linkedin-in,
  xing,
  x-twitter,
  instagram
);

$icons: (
  search,
  download,
  close,
  chevron-up,
  chevron-right,
  chevron-down,
  chevron-left,
  arrow-up,
  arrow-right,
  arrow-down,
  arrow-left,
  chart-column,
  chart-line,
  table
);

@at-root {
  .#{fa.$css-prefix},
  [class*="#{fa.$css-prefix}-"] {
    @extend %srl-icon-base;
  }
}

@each $name in $brands {
  .#{fa.$css-prefix}-#{$name} {
    @include fa.brands($name);
  }
}

@each $name in $icons {
  .#{fa.$css-prefix}-#{$name} {
    @include fa.icon($name);
  }
  .#{fa.$css-prefix}-thin-#{$name} {
    @include fa.thin($name);
  }
  .#{fa.$css-prefix}-light-#{$name} {
    @include fa.light($name);
  }
  .#{fa.$css-prefix}-regular-#{$name} {
    @include fa.regular($name);
  }
  .#{fa.$css-prefix}-solid-#{$name} {
    @include fa.solid($name);
  }
}

@use "srl";
@use "srl/fa";

.srl-checkbox {
  display: flex;
  @include srl.spacer-gap(100);
  align-items: flex-start;
  justify-content: flex-start;
  cursor: pointer;
  input[type="checkbox"] {
    display: none;
  }
  &:before {
    @include fa.base();
    @include fa.content(circle-x);
    @include fa.size(20);
    display: block;
    text-align: center;
    width: srl.system-size-unit(24);
    transform: translateY(srl.system-size-unit(12));
    color: red;
  }

  &:has(input[type="checkbox"]:checked) {
    &:before {
      @include fa.content(square-check);
      color: green;
    }
  }
}

@use 'srl';
@use 'web';

$editor-color-srl: srl.colors-shade-200();
$editor-background-color-srl: srl.colors-primary-1000();

/*
  Overruling Livingdocs editor styles
*/
.srl-article-root .doc-component-highlight {
  outline: 1px solid $editor-color-srl;
  border-radius: 0;
}

.srl-temp-highlight {
  background: #FFFF00;
}

span.srl-nowrap {
  --b: 1px; /* thickness of the border */
  --c: #{$editor-color-srl}; /* color of the border */
  --w: 6px; /* width of border */
  border: var(--b) solid #0000; /* space for the border */
  --_g: #0000 90deg, var(--c) 0;
  --_p: var(--w) var(--w) border-box no-repeat;
  background:
    conic-gradient(from 90deg at top var(--b) left var(--b), var(--_g)) 0 0 / var(--_p),
    conic-gradient(from 180deg at top var(--b) right var(--b), var(--_g)) 100% 0 / var(--_p),
    conic-gradient(from 0deg at bottom var(--b) left var(--b), var(--_g)) 0 100% / var(--_p),
    conic-gradient(from -90deg at bottom var(--b) right var(--b), var(--_g)) 100% 100% / var(--_p);
}

span.srl-key-figure {
  color: srl.colors-white-1000();
  background-color: $editor-background-color-srl;
}

// Set width of placeholder image to 100%
img[src^="data:image/svg+xml"] {
  width: 100%
}

.srl-editor-component {
  @include srl.spacer-padding-block(200);
  @extend %srl-grid-base;

  &.srl-pdf-pagebreak,
  &.srl-pdf-columnbreak,
  &.srl-anchor {
    border-top: 1px solid #{srl.colors-primary-1000()};
    border-bottom: 1px solid #{srl.colors-primary-1000()};
  }

  &.srl-pdf-publication-title,
  &.srl-pdf-chapter-title {
    border-bottom: 1px solid #{srl.colors-primary-1000()};
  }

  .doc-editable.doc-no-placeholder:before {
    display: none !important;
  }
}

.srl-editor-component__text {
  @extend %srl-regular-width;
  display: flex;
  flex-direction: column;

  &:after {
    order: -1;
    display: block;
    @include srl.typography-editor-label-text();

    .srl-anchor & {
      content: "Anchor:";
    }

    .srl-pdf-publication-title & {
      content: "PDF publication title:"
    }

    .srl-pdf-chapter-title & {
      content: "PDF chapter title:"
    }
  }
}

@use 'srl';
@use "srl/fa";
@use 'sass:string';
@use 'sass:map';
@use "components/button";
@use "components/fontawesome";
//@use 'components/icons';

$font-weight-bold: map.get(srl.$meta, font, weight, bold);

@include srl.system-add-root-style('srl-default-border-radius', srl.system-size-unit(16, pt));
@include srl.system-add-root-style('srl-default-border-radius', srl.system-size-unit(16));

@include srl.system-add-root-style('srl-model-flex-direction', column);
@include srl.system-add-root-style('srl-model-flex-direction', row, tablet-pt, up);

body {
  @include srl.typography-paragraph();
  background: srl.colors-white-1000();
  color: srl.colors-black-1000();
}

/*
  Images
*/
img {
  max-width: 100%;
  width: 100%;
  height: auto;
  display: block;
}

/*
  Bold styles
*/
[class*="bold"],
strong,
b {
    font-weight: #{$font-weight-bold};
}

/*
  Subscripts and superscripts
*/
.subscript,
sub,
.superscript,
sup {
  font-size: 60%;
  font-variant-numeric: tabular-nums;
  line-height: 0; // prevents normal text from getting too much height
}

.subscript,
sub {
  vertical-align: sub;
}

.superscript,
sup {
  vertical-align: super;
}

/*
  Nowrap's
*/
span {
  &[class*="nowrap"],
  &[class*="key-figure"] {
    white-space: nowrap;
  }
}

.srl-highlight {
  color: srl.colors-primary-1000();
}

.srl-linkable {
  a {
    color: srl.colors-primary-1000();
    text-decoration: underline;

    &:hover {
      text-decoration: none;
    }

    &[target="_blank"] {
      &:after {
        @extend %srl-icon-base;
        @include fa.content(arrow-up-right-from-square);
        margin-inline-start: .25em;
      }
    }
  }
}

.srl-flex {
  display: flex;
  flex-direction: srl.system-root-style(srl-model-flex-direction);
  gap: var(--srl-gutter-column-gap);
}

.srl-justify-self-center {
  justify-self: center;
}

.text-center {
  text-align: center;
}

@use 'srl';
@use 'print';
@use 'sass:map';

$image-quality: map.get(srl.$meta, pdf, image-quality);
$page-margin-top: srl.system-size-unit(map.get(srl.$meta, pdf, margin, top));
$page-margin-right: srl.system-size-unit(map.get(srl.$meta, pdf, margin, right));
$page-margin-bottom: srl.system-size-unit(map.get(srl.$meta, pdf, margin, bottom));
$page-margin-left: srl.system-size-unit(map.get(srl.$meta, pdf, margin, left));

/*
  Basic styles for PDF
*/
img {
  image-rendering: auto;
  -ro-image-resampling: $image-quality;
  -ro-pdf-tag-type: "Figure";

  &[alt] {
    -ro-pdf-tag-alt: attr(alt);
  }
}

[style*="--xlarge-url"] {
  background-image: var(--xlarge-url) !important;
}

/*
  Basic layout for PDF
*/
@page {
  margin: (
          $page-margin-top
          $page-margin-right
          $page-margin-bottom
          $page-margin-left
  );
  counter-increment: page 1;
  -ro-bleed-width: 0mm;
  -ro-media-size: A4;
  -ro-crop-size: media;
  -ro-truncate-margin-after-break: always;
  -ro-truncate-margin-before-break: always;

  @top-left-corner {
    content: element(publicationTitle);
    position: absolute;
    top: srl.spacer-get(400);
    left: $page-margin-left;
    z-index: 1;
  }

  @top-left {
    content: element(chapterNavigation);
    position: absolute;
    top: srl.spacer-get(400);
    left: srl.grid-calculate-pdf-col-span-plus-one-gutter(2);
    z-index: 1;
  }

  @top-right-corner {
    content: counter(page);
    position: absolute;
    top: srl.spacer-get(400);
    right: $page-margin-right;
    z-index: 1;
    @include srl.typography-pdf-header();
  }
}

/*
  Subscripts and superscripts
*/
.subscript,
sub,
.superscript,
sup {
  line-height: initial;
}

/*
  Page breaks for PDF
*/
.srl-chapter,
.srl-article {
  break-after: always;

  &:last-child {
    break-after: avoid;
  }
}

[class*="srl-category-notes_"],
[class*="srl-category-notes-"],
[class*="srl-category-note_"],
[class*="srl-category-note-"] {
  break-after: unset;

  &.last-note {
    break-after: always;
  }
}

/*
  Hold titles and the following component on the same page
*/
.srl-title-h1,
.srl-title-h2,
.srl-title-h3,
.srl-title-h4,
.srl-title-h5 {
  & + * {
    break-before: avoid;
  }
}

@use "srl/helpers";
@use "srl/system";
@use "srl/grid";

%srl-breakout-grid-base {
  @include grid.media-up(desktop) {
    display: grid;
    gap: var(--srl-gutter-column-gap);
    grid-template-columns:
    [full-start] minmax(0, 1fr)
    [content-start] repeat(var(--srl-gutter-columns), [col] minmax(0, calc((min(100vw, calc(var(--srl-container-max-width) - calc(var(--srl-gutter-column-gap) * 2))) - calc(var(--srl-gutter-columns) - 1) * var(--srl-gutter-column-gap)) / var(--srl-gutter-columns))))
    [content-end] minmax(0, 1fr)
    [full-end];
  }
}

%srl-breakout-grid-inner {
  @include system.add-root-style(srl-breakout-grid-from, content-start);
  @include system.add-root-style(srl-breakout-grid-to, content-end);

  @include grid.media-up(desktop) {
    padding: 0;
    margin: 0;
    display: grid;
    grid-template-columns: subgrid;
    position: relative;
    grid-row: 1;
    grid-column: system.root-style(srl-breakout-grid-from) / system.root-style(srl-breakout-grid-from);
  }
}

@mixin srl-breakout-grid-from-to($from: "full-start", $to: "full-end") {
  grid-column: $from / $to;
}

@use "srl/system";
@use "srl/colors";
@use "srl/spacer";
@use "srl/typography";
@use "srl/fa";
@use "srl/button";

$animation-duration: .3s;

@include system.add-root-style(srl-button-color, colors.black-1000());
@include system.add-root-style(srl-button-bg-color, colors.white-1000());
@include system.add-root-style(srl-button-brd-color, colors.grey-600());
@include system.add-root-style(srl-button-brd-size, system.size-unit(1));
@include system.add-root-style(srl-button-height, 3.5em);
@include system.add-root-style(srl-button-gap, spacer.get(100));
@include system.add-root-style(srl-button-brd-radius, calc( 3.5em / 2 ));
@include system.add-root-style(srl-button-padding-inline, spacer.get(300));
@include system.add-root-style(srl-button-image-size, 1em);

@include system.add-root-style(srl-button-hover-color, colors.white-1000());
@include system.add-root-style(srl-button-hover-bg-color, colors.grey-600());
@include system.add-root-style(srl-button-hover-brd-color, colors.grey-600());

@include system.add-root-style(srl-button-focus-color, colors.white-1000());
@include system.add-root-style(srl-button-focus-bg-color, colors.primary-1000());
@include system.add-root-style(srl-button-focus-brd-color, colors.primary-1000());

@include system.add-root-style(srl-button-active-color, colors.white-1000());
@include system.add-root-style(srl-button-active-bg-color, colors.primary-1000());
@include system.add-root-style(srl-button-active-brd-color, colors.primary-1000());

%srl-button {
  @include typography.button-text();
  column-gap: system.root-style(srl-button-gap);
  height: system.root-style(srl-button-height);
  align-items: center;
  justify-content: center;
  color: var( --srl-button-color-override, system.root-style(srl-button-color) );
  background-color: var( --srl-button-bg-color-override, system.root-style(srl-button-bg-color) );
  padding-inline: system.root-style(srl-button-padding-inline);
  border: system.root-style(srl-button-brd-size) solid var( --srl-button-brd-color-override, system.root-style(srl-button-brd-color) );
  border-radius: system.root-style(srl-button-brd-radius);
  text-decoration: none;
  text-box-trim: trim-both;
  cursor: pointer;

  &:not([hidden]) {
    display: inline-flex;
  }

  @if (system.$build == 'app') {
    transition:
            color $animation-duration ease-out,
            background-color $animation-duration ease-out,
            border-color $animation-duration ease-out,
            border-radius $animation-duration ease-out;
  }

  &:hover {
    color: var(--srl-button-color-override, system.root-style(srl-button-hover-color));
    background-color: var(--srl-button-bg-color-override, system.root-style(srl-button-hover-bg-color));
    border-color: var(--srl-button-brd-color-override, system.root-style(srl-button-hover-brd-color));
  }

  &:focus,
  &:focus-visible {
    color: var(--srl-button-color-override, system.root-style(srl-button-focus-color));
    background-color: var(--srl-button-bg-color-override, system.root-style(srl-button-focus-bg-color));
    border-color: var(--srl-button-brd-color-override, system.root-style(srl-button-focus-brd-color));
    outline: none   ;

    &[aria-expanded="false"] {
      color: var( --srl-button-color-override, system.root-style(srl-button-color) );
      background-color: var( --srl-button-bg-color-override, system.root-style(srl-button-bg-color) );
      border: system.root-style(srl-button-brd-size) solid var( --srl-button-brd-color-override, system.root-style(srl-button-brd-color) );
    }
  }

  img, svg {
    width: auto;
    height: system.root-style(srl-button-image-size);
    color: inherit;
  }

  &.srl-active,
  &[aria-expanded="true"],
  &[aria-selected="true"],
  &[aria-current="page"]
  {
    color: system.root-style(srl-button-active-color);
    background-color: system.root-style(srl-button-active-bg-color);
    border-color: system.root-style(srl-button-active-brd-color);
  }
}

%srl-button--ghost {
  --srl-typo-button-text-font-family: inherit;
  --srl-typo-button-text-font-size: inherit;
  --srl-typo-button-text-font-weight: inherit;
  --srl-typo-button-text-line-height: inherit;
  --srl-button-color: inherit;
  --srl-button-bg-color: transparent;
  --srl-button-brd-radius: 0;
  --srl-button-height: auto;
  --srl-button-brd-size: 0;
  --srl-button-padding-inline: 0;
