@use "srl/grid";

%srl-trim-margins {
  @include helpers.trim-margins;
}

%srl-grid-base {
  @if system.$build == "pdf" {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
  } @else if system.$build == "word" {
    display: block;
    margin-left: 0;
    margin-right: 0;
    padding-left: 0;
    padding-right: 0;
  } @else {
    margin-left: auto;
    margin-right: auto;
    @include grid.container();
    @include grid.row();
  }
}

%srl-grid-reset {
  padding: 0;
  margin-left: 0;
  margin-right: 0;
  max-width: 100%;
  display: block;
}

%srl-regular-width {
  @if system.$build == "xbrl" {
    @include grid.col(6);
    @include grid.offset(3);
  } @else if system.$build == "pdf" {
    @include grid.pdf-flex-col(6);
  } @else {
    // Mobile
    @include grid.col(4);

    // Mobile landscape
    @include grid.col(4, phone-ls);

    // Tablet portrait
    @include grid.col(8, tablet-pt);

    // Tablet landscape
    @include grid.col(8, tablet-ls);
    @include grid.offset(2, tablet-ls);

    // Desktop
    @include grid.col(6, desktop);
    @include grid.offset(3, desktop);

    // Desktop large
    @include grid.col(6, desktop-large);
    @include grid.offset(3, desktop-large);
  }
}

%srl-wide-width {
  @if system.$build == "xbrl" {
    @include grid.col(12);
    @include grid.offset(0);
  } @else if system.$build == "pdf" {
    @include grid.pdf-flex-col(8);
  } @else {
    // Mobile
    @include grid.col(4);

    // Mobile landscape
    @include grid.col(4, phone-ls);

    // Tablet portrait
    @include grid.col(8, tablet-pt);

    // Tablet landscape
    @include grid.col(12, tablet-ls);
    @include grid.offset(0, tablet-ls);

    // Desktop
    @include grid.col(12, desktop);
    @include grid.offset(0, desktop);

