styles.source:
@use 'srl';
@use 'web';
@use "sass:map";

$marker-width: srl.system-size-unit(map.get(srl.$meta, list, marker-width-pdf));
$nested-marker-width: calc(#{$marker-width} * 1.5);
$deep-nested-marker-width: calc(#{$marker-width} * 2);

.srl-list-group__item-inner {
  -ro-pdf-tag-type: LI;

  &:before {
    width: $marker-width;
    -ro-pdf-tag-type: Lbl;
  }
}

.srl-list-group__item-text {
  -ro-pdf-tag-type: LBody;

  .srl-table-list--ul &,
  .srl-list-group--ul & {
    width: calc(100% - #{$marker-width});
  }
}

.srl-list-group__sub-list--ol .srl-list-group__item-inner:before {
  width: $nested-marker-width;
}

.srl-list-group__sub-list--ol .srl-list-group__item-text {
  width: calc(100% - #{$nested-marker-width});
}

.srl-list-group__sub-list--ol .srl-list-group__sub-list--ol .srl-list-group__item-inner:before {
  width: $deep-nested-marker-width;
}

.srl-list-group__sub-list--ol .srl-list-group__sub-list--ol .srl-list-group__item-text {
  width: calc(100% - #{$deep-nested-marker-width});
}

.srl-list-group__sub-list {
  -ro-pdf-tag-type: L;
  padding: 0 0 0 $marker-width;
}

@use 'srl';
@use "sass:map";

$marker-width: srl.system-size-unit(map.get(srl.$meta, list, marker-width));
$number-width: srl.system-size-unit(map.get(srl.$meta, footnote, number-width));
$nested-marker-width: calc(#{$marker-width} * 1.5);
$unordered-marker: "–";
$ordered-marker-after: ".";
$alphanumeric-marker-after: ")";

.srl-list-group__item-inner {
  display: flex;

  &:before {
    width: $marker-width;

    .srl-table-list--ul &,
    .srl-list-group--ul & {
      content: "#{$unordered-marker}";
    }

    .srl-table-list--ol &,
    .srl-list-group--ol & {
      counter-increment: ordered-list;
      content: counters(ordered-list, ".") $ordered-marker-after;
      font-variant-numeric: tabular-nums;
    }

    .srl-table-list--alphanumeric &,
    .srl-list-group--alphanumeric & {
      counter-increment: alphanumeric-list;
      content: counter(alphanumeric-list, lower-alpha) $alphanumeric-marker-after;
    }
  }
}

.srl-list-group__item-text {
  width: calc(100% -  #{$marker-width});

  .srl-table-list--ul &,
